    }
    expect([...PLAN_ORDER].sort()).toEqual([...PLAN_IDS].sort());
  });

  it("never shrinks a quota as the plan gets richer", () => {
    for (const resource of RESOURCES) {
      for (let i = 1; i < PLAN_ORDER.length; i += 1) {
        const previous = PLAN_ORDER[i - 1];
