cat > src/schemas/recurring-issue.ts <<'EOF'
import { z } from "zod";
import { orgIdSchema, projectIdSchema, userIdSchema } from "./common";
import { issuePrioritySchema } from "./issue";

const recurrenceCadenceSchema = z.enum(["daily", "weekly"]);

const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** A real `YYYY-MM-DD` day: `2026-02-30` matches the shape but is not a date. */
function isCalendarDate(value: string): boolean {
  const match = CALENDAR_DATE.exec(value);
  if (match === null) return false;

  const [year, month, day] = [Number(match[1]), Number(match[2]), Number(match[3])];
  // `setUTCFullYear` rather than `Date.UTC`, which maps years 0-99 to 19xx.
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);

  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/**
 * True for a zone name the runtime's ICU data knows. Fixed-offset spellings
 * such as `+05:00` are accepted by `Intl` but are not IANA zones, and they
 * carry no daylight-saving rules, so they are refused here.
 */
function isKnownTimeZone(value: string): boolean {
  if (value.length === 0 || value.startsWith("+") || value.startsWith("-")) {
    return false;
  }
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: value });
    return true;
  } catch {
    return false;
  }
}

export const createRecurringIssueSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema,
    title: z.string().min(3, "give the recurring issue a title").max(180),
    priority: issuePrioritySchema.default("none"),
    assigneeId: userIdSchema.nullable().default(null),
    cadence: recurrenceCadenceSchema,
    weekday: z.number().int().min(1).max(7).nullable().default(null),
    timezone: z
      .string()
      .refine(isKnownTimeZone, "timezone must be an IANA time zone"),
    startsOn: z
      .string()
      .refine(isCalendarDate, "startsOn must be a real YYYY-MM-DD date"),
  })
