/**
 * Recurring-issue rules. Every read except the job's work list takes `orgId`
 * first; rules are never deleted, only paused.
 */
import { and, asc, count, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toRecurringIssue } from "./_mappers";
import type { OrgId } from "@/types/common";
import type { RecurringIssue } from "@/types/recurring-issue";

/** The caller-supplied part of a rule; the rest is stamped on insert. */
export type NewRecurringIssue = Pick<
  RecurringIssue,
  | "orgId"
  | "projectId"
  | "title"
  | "priority"
  | "assigneeId"
  | "cadence"
  | "weekday"
  | "timezone"
  | "startsOn"
>;

/** Insertion order: `rowid` is monotonic, unlike a millisecond timestamp. */
const CREATION_ORDER = sql`rowid`;

export async function findRecurringIssueById(
  orgId: OrgId,
  recurringIssueId: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .get();
  return row ? toRecurringIssue(row) : null;
}

export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(CREATION_ORDER)
    .all();
  return rows.map(toRecurringIssue);
}

/**
 * The job's work list: every rule that is not paused, across all
 * organizations. This is the one deliberately un-scoped read — the job acts
 * for each rule's own organization, never for a caller's.
 */
export async function listUnpausedRecurringIssues(): Promise<
  readonly RecurringIssue[]
> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(CREATION_ORDER)
    .all();
  return rows.map(toRecurringIssue);
}

/** Every rule counts toward the plan cap, paused ones included. */
export async function countRecurringIssues(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

/**
 * Inserts a rule unless `isAtQuota(used)` says the organization is already
 * full, returning `null` in that case. The count and the insert share one
 * transaction with no `await` between them, so two concurrent creations
 * cannot both slip under the cap.
 */
export async function insertRecurringIssue(
  input: NewRecurringIssue,
  createdBy: RecurringIssue["createdBy"],
  isAtQuota: (used: number) => boolean,
): Promise<RecurringIssue | null> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const used =
      tx
        .select({ value: count() })
        .from(recurringIssues)
        .where(orgPredicate(recurringIssues.orgId, input.orgId))
        .get()?.value ?? 0;
    if (isAtQuota(used)) return null;

    const row = tx
      .insert(recurringIssues)
      .values({
        id: newId(),
        orgId: input.orgId,
        projectId: input.projectId,
        title: input.title,
        priority: input.priority,
        assigneeId: input.assigneeId,
        cadence: input.cadence,
        weekday: input.weekday,
        timezone: input.timezone,
        startsOn: input.startsOn,
        lastOccurrenceOn: null,
        paused: false,
        createdBy,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    return toRecurringIssue(row);
  });
}

export async function setRecurringIssuePaused(
  orgId: OrgId,
  recurringIssueId: string,
  paused: boolean,
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Recurring issue ${recurringIssueId} not found`);
  return toRecurringIssue(row);
}

/** Records the occurrence day the job last filed an issue for. */
export async function setLastOccurrenceOn(
  orgId: OrgId,
  recurringIssueId: string,
  occurrenceOn: string,
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({
      lastOccurrenceOn: occurrenceOn,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Recurring issue ${recurringIssueId} not found`);
  return toRecurringIssue(row);
}
EOF

