export async function createRecurringIssue(
  actor: Actor,
  input: CreateRecurringIssueInput,
): Promise<RecurringIssue> {
  const rule = createRecurringIssueSchema.parse(input);

  assertOrgScope(actor, rule.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(rule.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  if (rule.assigneeId !== null) {
    const assignee = await memberRepo.findMember(rule.orgId, rule.assigneeId);
    if (assignee === null || assignee.status !== "active") {
      throw new Error(
        `User ${rule.assigneeId} is not an active member of organization ${rule.orgId}`,
      );
    }
  }

  const org = requireFound(
    await orgRepo.findOrgById(rule.orgId),
    "Organization",
    rule.orgId,
  );

  const created = await recurringIssueRepo.insertRecurringIssue(
    rule,
    actor.userId,
    (used) => wouldExceedLimit(org.plan, "recurringIssues", used),
  );
  if (created === null) {
    throw new Error(`Plan ${org.plan} allows no more recurring issues`);
  }

  return created;
}

/** Pausing takes the permission that creating the rule's issues would. */
export async function setRecurringIssuePaused(
  actor: Actor,
  input: { orgId: OrgId; recurringIssueId: string; paused: boolean },
): Promise<RecurringIssue> {
  assertOrgScope(actor, input.orgId);

  const rule = requireFound(
    await recurringIssueRepo.findRecurringIssueById(
      input.orgId,
      input.recurringIssueId,
    ),
    "RecurringIssue",
    input.recurringIssueId,
  );

  const project = requireFound(
    await projectRepo.findProjectById(rule.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  assertCan(actor, "issue:create", projectResource(project));

  if (rule.paused === input.paused) return rule;

  return recurringIssueRepo.setRecurringIssuePaused(
    input.orgId,
    rule.id,
    input.paused,
  );
}

/** Rules in creation order; like the org-wide issue list, an `issue:read`. */
export async function listRecurringIssues(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "issue:read", orgResource(orgId));
  return recurringIssueRepo.listRecurringIssues(orgId);
}
